<div class="card"><div class="card-header"><h3 class="card-title">Documentos aguardando ou em inspeção</h3></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Documento</th><th>Fornecedor</th><th>Obrigação</th><th>Valor</th><th>Status</th><th>Lançamento</th></tr></thead><tbody><?php foreach($itens as $i):?><tr><td><a href="/documentos/<?=e($i['documento_id'])?>"><strong><?=e($i['tipo_documento'])?> <?=e($i['documento_numero'])?></strong></a><div class="small text-body-secondary"><?=e($i['data_documento'])?></div></td><td><?=e($i['fornecedor'])?></td><td><?=e($i['obrigacao_numero'])?>/<?=e($i['obrigacao_ano'])?></td><td><?=money($i['valor_bruto'])?></td><td><span class="badge <?=$i['permite_avancar']?'text-bg-success':'text-bg-warning'?>"><?=e($i['status_inspecao'])?></span></td><td><?=e($i['data_lancamento'])?></td></tr><?php endforeach;?><?php if(!$itens):?><tr><td colspan="6" class="text-center text-body-secondary py-4">Fila vazia.</td></tr><?php endif;?></tbody></table></div></div>